      "b,free,dt){\n    if(free) return;\n    var tg=Math.atan2(b.nx,b.ny), k=1-Math.exp(-dt/0.07);\n    b.ang+=(tg-b.ang)*k;\n    b.nx=Math.sin(b.ang); b.ny=Math.cos(b.an",
      "g);\n  }\n\n  /* --- P：CD → BC → 圆弧AB →（到顶自然折返或竖直飞出）→ 沿弧返回 → BC → CD → D 处 --- */\n  function stepP(dt){\n    var b=p;\n    if(b.mode==='flat'){\n      if(b.x<=xC+1e-9",
      "&&b.v!==0){\n        var a=-Math.sign(b.v)*mu*g, nv=b.v+a*dt;\n        b.v=(nv*b.v<0)?0:nv;\n      }\n      b.x+=b.v*dt; b.y=0; b.nx=0; b.ny=1;\n      if(b.v<0&&b.x<",
      "=xB){ b.x=xB; b.mode='arc'; b.th=0; b.thd=-b.v/R1; }\n      else if(b.v>0&&b.x>=0){\n        b.x=0; pBack=true;\n        if(c.X>0.14){ b.mode='fall'; b.vx=b.v; b.v",
      "y=0; }\n        else { b.v=0; b.mode='rest'; }\n      }\n    } else if(b.mode==='arc'){\n      b.thd+=(-g/R1)*Math.sin(b.th)*dt;\n      b.th+=b.thd*dt;\n      if(b.th",
