      "\n  ctx.restore();\n}\nfunction block(x,y,nx,ny,bw,bh,col,tag){\n  var cx=x+nx*bh/2, cy=y+ny*bh/2, ang=Math.atan2(nx,ny);\n  drawSprite(tag==='P'?'P':'Q',cx,cy,bw,bh",
      ",ang,col,1);\n}\nvar LABF=[['A',-4.438,1.232,0],['B',-2.893,-0.302,0],['C',-2.354,-0.302,0],['D',-0.240,-0.176,0],\n          ['O',-2.748,1.162,1],['R',-2.772,0.59",
