      "\n  var px=X(wx), py=Y(wy);\n  ctx.fillText(txt,px,py);\n  if(!idx) return;\n  ctx.font='italic '+sub+'px \"Times New Roman\",Georgia,serif';\n  ctx.fillText(''+idx,px",
      "+fs*0.36,py+sub*0.30);\n  ctx.font='italic '+fs+'px \"Times New Roman\",Georgia,serif';\n}\n/* ================= 主绘制 ================= */\nfunction draw(){\n  layoutSt",
