      "I.t>=UI.sim.tEnd){ UI.t=UI.sim.tEnd; UI.playing=false; syncPlay(); }\n    syncProg();\n  }\n  draw();\n  requestAnimationFrame(loop);\n}\n\n/* ================= 控件 ===",
