      "Ep','Ep',0,' J');\nbindRange('sMu','vMu','mu',2,'');\nbindRange('sM3','vM3','m3',1,' kg');\nbindRange('sR2','vR2','R2',2,' m');\nbindRange('sW','vW','w',1,'');\n\n(fu",
