      "nst items = [], off = [];\n  LABELS.forEach(function (it) {\n    const sp = it.sp;\n    if (!sp || !chainVisible(sp)) return;\n    const wp = sp.getWorldPosition(ne",
      "w THREE.Vector3());\n    const c = toPx(wp);\n    const rx = toPx(wp.clone().add(new THREE.Vector3(sp.userData.hwU, 0, 0)));\n    const ry = toPx(wp.clone().add(ne",
      "w THREE.Vector3(0, sp.userData.hhU, 0)));\n    const hw = Math.abs(rx.x - c.x), hh = Math.abs(ry.y - c.y);\n    items.push({ n: it.n, x: c.x, y: c.y, hw: hw, hh: ",
