      "\tTWO: THREE.TOUCH.DOLLY_PAN\n\t\t\t}; // for reset\n\n\t\t\tthis.target0 = this.target.clone();\n\t\t\tthis.position0 = this.object.position.clone();\n\t\t\tthis.zoom0 = this.ob",
