      "heduleRuntimeInfo();\r\n}\r\n\r\n/* ---------- 标签精灵 ---------- */\r\nfunction regLabel(name, sp) {\r\n  let n = name, k = 2;\r\n  while (LABELS.some(function (o) { return o",
      ".n === n; })) n = name + '#' + (k++);\r\n  LABELS.push({ n: n, sp: sp });\r\n  return sp;\r\n}\r\nfunction makeLabelSprite(text, color, size) {\r\n  const c = document.cr",
