      "().add(new THREE.Vector3(0, sp.userData.hhU, 0)));\r\n    const hw = Math.abs(rx.x - c.x), hh = Math.abs(ry.y - c.y);\r\n    items.push({ n: it.n, x: c.x, y: c.y, h",
      "w: hw, hh: hh });\r\n    if (c.x - hw < 0 || c.x + hw > w || c.y - hh < 0 || c.y + hh > h) off.push(it.n);\r\n  });\r\n  let minGap = 1e9, worst = '-';\r\n  const hits ",
      "= [], pairs = [];\r\n  for (let i = 0; i < items.length; i++) {\r\n    for (let j = i + 1; j < items.length; j++) {\r\n      const A = items[i], B = items[j];\r\n      ",
      "const gx = Math.abs(A.x - B.x) - 0.72 * (A.hw + B.hw);\r\n      const gy = Math.abs(A.y - B.y) - 0.72 * (A.hh + B.hh);\r\n      const g = Math.max(gx, gy);\r\n      i",
      "f (g < minGap) { minGap = g; worst = A.n + '/' + B.n; }\r\n      if (g < 0) hits.push(A.n + '/' + B.n);\r\n      pairs.push({ p: A.n + '/' + B.n, g: +g.toFixed(1) }",
      ");\r\n    }\r\n  }\r\n  pairs.sort(function (a, b) { return a.g - b.g; });\r\n  const ovs = overlayRects(), onOv = [];\r\n  items.forEach(function (A) {\r\n    ovs.forEach(",
      "function (o) {\r\n      const dx = Math.abs(A.x - o.x - o.w / 2) - 0.72 * A.hw - o.w / 2;\r\n      const dy = Math.abs(A.y - o.y - o.h / 2) - 0.72 * A.hh - o.h / 2;",
