      "AXX, 0, 0), new THREE.Vector3(0, 0, 0), 0x7fd0f5, 0.85, true);\r\n  rule2 = segLine(new THREE.Vector3(AXX, 0, 0), new THREE.Vector3(0, 0, 0), 0xffc861, 0.85, true",
      ");\r\n  rulePtr = segLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0, 0), 0xffc861, 0.75, true);\r\n  scene.add(rule1); scene.add(rule2); scene.add(rulePtr)",
      ";\r\n\r\n  /* 解锁闪光（两个） */\r\n  const mkFlash = function (color) {\r\n    const m = new THREE.Mesh(new THREE.RingGeometry(0.30, 0.40, 44),\r\n      new THREE.MeshBasicMate",
