      " 'x' + Math.round(chartH),\r\n      topOverlay: Math.round(topOverlayPx(freeBand().x0, freeBand().x1)),\r\n      bottomOverlay: Math.round(bottomOverlayPx(freeBand(",
      ").x0, freeBand().x1))\r\n    };\r\n    const lf = checkLabels();\r\n    if (lf) info.labelFit = lf; else delete info.labelFit;\r\n    info.sim = { T: +PH.T.toFixed(3), ",
      "Tprob: +PH.Tprob.toFixed(3), Tm: +WARP.Tm.toFixed(3),\r\n                 t: +simT.toFixed(3), key: curKey(), fut: chartIsFut(), chartMode: chartIsFut() ? 'fut' :",
      " 'prob' };\r\n    el.textContent = JSON.stringify(info);\r\n  } catch (e) { }\r\n}\r\nlet _infoTm = 0;\r\nfunction scheduleRuntimeInfo() {\r\n  clearTimeout(_infoTm);\r\n  _i",
