      "assList.contains('collapsed');\r\n  const need = collapsed ? 0 : ((body ? body.scrollHeight : 0) + (head ? head.offsetHeight : 0) +\r\n    (tabs && tabs.offsetHeigh",
      "t ? tabs.offsetHeight : 0) + 2);\r\n  if (lg && !lg.classList.contains('off')) {\r\n    const r = lg.getBoundingClientRect();\r\n    if (r.height > 1) lg._h = r.heigh",
      "t;\r\n  }\r\n  const legendTopEst = panelTop - 8 - (lg ? (lg._h || 32) : 0);\r\n  const availWith = legendTopEst - 8 - top;\r\n  const availWout = panelTop - 8 - top;\r\n",
      "  const off = !collapsed && need > availWith;\r\n  if (lg) lg.classList.toggle('off', off);\r\n  const avail = off ? availWout : availWith;\r\n  stem.style.maxHeight ",
      "= Math.max(170, Math.min(avail, window.innerHeight * 0.66)) + 'px';\r\n  updateStemMore();\r\n}\r\n\r\n/* 底部渐隐只在\"确实还有下文\"时出现，滚到底就消失 */\r\nfunction updateStemMore() {\r\n  co",
      "nst stem = document.getElementById('stem');\r\n  const body = document.getElementById('stemBody');\r\n  if (!stem || !body) return;\r\n  const over = !stem.classList.",
      "contains('collapsed') &&\r\n    body.scrollHeight - body.clientHeight > 2 &&\r\n    body.scrollTop + body.clientHeight < body.scrollHeight - 2;\r\n  stem.classList.to",
      "ggle('hasMore', over);\r\n}\r\n\r\n/* ---------- 取景 ---------- */\r\nfunction fitCamera() {\r\n  if (chartZoom) return;                  // 全屏看图时舞台被模态层盖住，不必重取景（否则退出会跳一下）\r",
      "\n  const w = stage.clientWidth, h = stage.clientHeight;\r\n  if (!w || !h || !camera) return;\r\n  /* 留边要按\"标签半宽\"算：精灵半宽约 25 px，16 px 的边距会把 D 的右半截切掉 */\r\n  const fB = ",
      "Math.min(0.40, (bottomOverlayPx() + 30) / h);\r\n  const fT = Math.min(0.30, (topOverlayPx() + 22) / h);\r\n  const fL = Math.min(0.40, (leftOverlayPx() + 26) / w);",
      "\r\n  const fR = Math.min(0.40, (rightOverlayPx() + 30) / w);\r\n  const allowY = Math.max(0.16, 2 * (1 - fT - fB));\r\n  const allowX = Math.max(0.42, 2 * (1 - fL - ",
      "fR));\r\n\r\n  const dir = VIEWS[curView].clone();\r\n  const upDir = (curView === 'top') ? new THREE.Vector3(0, 0, -1) : new THREE.Vector3(0, 1, 0);\r\n  const upP = u",
      "pDir.clone().addScaledVector(dir, -upDir.dot(dir));\r\n  if (upP.lengthSq() < 1e-8) upP.set(0, 0, -1);\r\n  upP.normalize();\r\n  const rightP = new THREE.Vector3().c",
      "rossVectors(upP, dir).normalize();\r\n\r\n  const corners = contentPts();\r\n  const c = boxCenter();\r\n  const tanV = Math.tan(camera.fov * Math.PI / 360);\r\n\r\n  camer",
      "a.up.copy(upDir);\r\n  camera.aspect = w / h;\r\n  camera.updateProjectionMatrix();\r\n\r\n  let d = LOOK.max.clone().sub(LOOK.min).length() * 0.92;\r\n  let shiftY = 0, ",
      "shiftX = 0, dbg = null;\r\n  const place = function () {\r\n    const target = c.clone().addScaledVector(upP, shiftY).addScaledVector(rightP, shiftX);\r\n    camera.p",
      "osition.copy(target).addScaledVector(dir, d);\r\n    camera.lookAt(target);\r\n    camera.updateMatrixWorld();\r\n    return target;\r\n  };\r\n  for (let it = 0; it < 12",
      "; it++) {\r\n    place();\r\n    let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;\r\n    for (let i = 0; i < corners.length; i++) {\r\n      const v = corners[i].c",
      "lone().project(camera);\r\n      if (v.x < minX) minX = v.x; if (v.x > maxX) maxX = v.x;\r\n      if (v.y < minY) minY = v.y; if (v.y > maxY) maxY = v.y;\r\n    }\r\n  ",
      "  const k = Math.max((maxX - minX) / allowX, (maxY - minY) / allowY);\r\n    const bandCy = fB - fT, bandCx = fL - fR;\r\n    const cy = (minY + maxY) / 2, cx = (mi",
      "nX + maxX) / 2;\r\n    const H = d * tanV, Wd = H * camera.aspect;\r\n    dbg = { it: it, k: +k.toFixed(3), d: +d.toFixed(2), shiftY: +shiftY.toFixed(2), shiftX: +s",
      "hiftX.toFixed(2),\r\n            allowX: +allowX.toFixed(3), allowY: +allowY.toFixed(3),\r\n            minX: +minX.toFixed(3), maxX: +maxX.toFixed(3), minY: +minY.",
