      "*= 1 + (k - 1) * 0.92;\r\n    if (Math.abs(k - 1) < 0.004 && Math.abs(cy - bandCy) < 0.012 && Math.abs(cx - bandCx) < 0.012) break;\r\n  }\r\n  FIT_DBG = dbg;\r\n  cons",
      "t target = place();\r\n  controls.target.copy(target);\r\n  if (curView !== 'top') controls.update();\r\n  scheduleRuntimeInfo();\r\n}\r\n\r\n/* ---------- 标签精灵 ---------- ",
      "*/\r\nfunction regLabel(name, sp) {\r\n  let n = name, k = 2;\r\n  while (LABELS.some(function (o) { return o.n === n; })) n = name + '#' + (k++);\r\n  LABELS.push({ n:",
      " n, sp: sp });\r\n  return sp;\r\n}\r\nfunction makeLabelSprite(text, color, size) {\r\n  const c = document.createElement('canvas');\r\n  c.width = 256; c.height = 128;\r",
      "\n  const g = c.getContext('2d');\r\n  let fs = 92;\r\n  g.font = 'bold ' + fs + 'px \"Microsoft YaHei\",sans-serif';\r\n  const tw = g.measureText(text).width;\r\n  if (t",
      "w > 236) {\r\n    fs = Math.max(26, Math.floor(fs * 236 / tw));\r\n    g.font = 'bold ' + fs + 'px \"Microsoft YaHei\",sans-serif';\r\n  }\r\n  g.textAlign = 'center'; g.",
      "textBaseline = 'middle';\r\n  g.shadowColor = 'rgba(2,6,14,.95)'; g.shadowBlur = 10;\r\n  g.fillStyle = color;\r\n  g.fillText(text, 128, 68);\r\n  const tex = new THRE",
