      "eak;\n\n\t\t\t\t\t\t\tdefault:\n\t\t\t\t\t\t\t\tstate = STATE.NONE;\n\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\tbreak;\n\n\t\t\t\t\tcase 2:\n\t\t\t\t\t\tswitch ( scope.touches.TWO ) {\n\n\t\t\t\t\t\t\tcase THREE.TOUCH.DOLLY_PAN:\n",
      "\t\t\t\t\t\t\t\tif ( scope.enableZoom === false && scope.enablePan === false ) return;\n\t\t\t\t\t\t\t\thandleTouchStartDollyPan( event );\n\t\t\t\t\t\t\t\tstate = STATE.TOUCH_DOLLY_PAN;",
