      "*/\r\nfunction washer(r0, r1, x0, th, mFace, mBand) {\r\n  const g = new THREE.Group();\r\n  const geo = new THREE.RingGeometry(r0 * SC, r1 * SC, 72, 1);\r\n  for (let ",
      "s = 0; s < 2; s++) {\r\n    const m = new THREE.Mesh(geo, mFace);\r\n    m.rotation.y = Math.PI / 2;\r\n    m.position.x = (x0 + (s ? th : 0)) * SC;\r\n    g.add(m);\r\n ",
