      "= -Math.PI / 2;\r\n    b.position.x = (x0 + th / 2) * SC;\r\n    g.add(b);\r\n  });\r\n  return g;\r\n}\r\nfunction circleLine(r, x, color, op) {\r\n  const pts = [];\r\n  for ",
