      "= Math.sin(a);\r\n    const g = ctx.arrow(0x63d6cf, 0.0048);\r\n    S.add(g);\r\n    ctx.setArrow(g, W(GEO.X0 + GEO.D * 0.5, rOut * cy, rOut * cz),\r\n      new THREE.V",
      "ector3(0, cy, cz).normalize(), 0.024 * SC, 0.85);\r\n    OBJ.b2Arr.push(g);\r\n    OBJ.b2Az.push(a);\r\n  }\r\n\r\n  /* ---- 电子轨道环 + 半径指示 ---- */\r\n  const orb = new THREE",
