      "+ s + '</i>'; }                              /* 公式/行文里的物理量 */\r\nfunction VS(s, sub) { return '<i>' + s + '</i><sub><i>' + sub + '</i></sub>'; }  /* 带拉丁下标 */\r\nfun",
      "ction KQ(s) { return '<i style=\"color:#ffd166\">' + s + '</i>'; }         /* 题干里的已知量：斜体 + 强调色 */\r\nfunction UN(s) { return NB + s; }                              ",
      "            /* 单位：正体 + 不换行空格 */\r\nconst C_BALL = 0xffd166, C_A = 0xffb347, C_B = 0x5ec8f0;\r\n\r\nfunction lineFrom(pts, color, opacity, dashed, dash, gap) {\r\n  cons",
      "t g = new THREE.BufferGeometry().setFromPoints(pts);\r\n  const m = dashed\r\n    ? new THREE.LineDashedMaterial({ color: color, dashSize: dash || 0.05, gapSize: ga",
      "p || 0.04, transparent: true, opacity: opacity })\r\n    : new THREE.LineBasicMaterial({ color: color, transparent: true, opacity: opacity });\r\n  const l = new TH",
      "REE.Line(g, m);\r\n  if (dashed) l.computeLineDistances();\r\n  return l;\r\n}\r\n\r\nfunction build(ctx) {\r\n  CTX = ctx;\r\n  /* 维护/自测用：带 ?dbg=1 打开时才挂，正常使用不产生任何全局变量 */\r\n  ",
      "if (/[?&]dbg=1/.test(location.search + '&' + location.hash)) {\r\n    window.__W = { scene: ctx.scene, camera: ctx.camera, stage: ctx.stage };\r\n  }\r\n  /* 引擎只在一处（r",
      "ebuildCase）与 resize 时刷新 #selftest 快照；键盘跳帧、\r\n     拖进度条、点关键帧都只改 simT 不重算快照，于是 sim.t 读到的是旧值\r\n     （无头下 rAF 停摆时尤其明显）。在捕获阶段补一发防抖重算，两行覆盖全部交互。 */\r\n  ['click', 'keydown",
      "', 'input', 'change', 'pointerup'].forEach(function (ev) {\r\n    document.addEventListener(ev, function () {\r\n      if (CTX && CTX.scheduleRuntimeInfo) CTX.sched",
      "uleRuntimeInfo();\r\n    }, true);\r\n  });\r\n  /* 引擎的 → 按「当前关键帧索引 +1」跳；而 ②③④ 的第一枚关键帧不在 t=0（是 t*），\r\n     于是从起点按 → 会越过「① 脱杆」直奔「② 落地」，那枚按钮等于键盘够不着。\r\n     窄口径修正：时间还在首帧之前",
      "时，→ 就点 ① 按钮（和学生手点的是同一颗），并吃掉事件。 */\r\n  document.addEventListener('keydown', function (e) {\r\n    if (e.code !== 'ArrowRight') return;\r\n    const ae = document.acti",
