      "nst K = (S && S.keys) || [];\r\n    if (!K.length || LIVE_T >= K[0].t - 1e-9) return;                /* 已在首帧之后，交回引擎 */\r\n    const b = document.getElementById('btn",
      "K0');\r\n    if (!b) return;\r\n    e.preventDefault(); e.stopPropagation();\r\n    b.click();\r\n  }, true);\r\n  const S = ctx.scene;\r\n\r\n  /* ---- 地面 + 网格 ---- */\r\n  co",
      "nst ground = new THREE.Mesh(new THREE.PlaneGeometry(46, 46),\r\n    new THREE.MeshStandardMaterial({ color: 0x060d1a, roughness: 0.98, metalness: 0.0 }));\r\n  grou",
      "nd.rotation.x = -Math.PI / 2;\r\n  ground.position.set(1.1, -0.002, 0);\r\n  S.add(ground);\r\n  const grid = ctx.grid(46, 46, 0.0, 0x2c4a78, 0x16263f);\r\n  grid.posit",
      "ion.x = 1.1;\r\n  S.add(grid);\r\n\r\n  /* ---- 地面固定点（铰座） ---- */\r\n  const matSteel = new THREE.MeshStandardMaterial({ color: 0x35527c, roughness: 0.42, metalness: 0.",
