      "indow.CASE = {\r\n  title: '轻杆脱球与弹射分裂 · 3D 演示',\r\n  hudTitle: '轻杆小球 · 脱杆与分裂',\r\n  stemTitle: '题干',\r\n  views: { iso: [0.62, 0.40, 0.68], face: [0.06, 0.10, 1], top: ",
