      "hh0 * k;\n  }\n}\n\nconst ARROW_HEAD_RATIO = 2.5;\nfunction makeArrow(color, radius) {\n  const g = new THREE.Group();\n  const mat = new THREE.MeshBasicMaterial({ col",
