      "ngClientRect().top;\n  const b = Math.max(8, window.innerHeight - top + 8);\n  const lg = document.querySelector('.legend');\n  if (lg) lg.style.bottom = b + 'px';",
      "\n  layoutStem();\n}\nfunction layoutStem() {\n  const stem = $('stem');\n  if (!stem) return;\n  const body = $('stemBody');\n  const head = $('stemHead');\n  const lg",
