      "n.y = 0;\n  if (CTX) CTX.invalidate({ look: true, chart: true });\n}\n\n/* ======================= 4. 每帧更新 ======================= */\nconst _d3 = new THREE.Vector3(",
      ");\nconst _p3 = new THREE.Vector3();\nconst UPV = new THREE.Vector3(0, 1, 0);\n\nfunction place(sp, p) {\n  sp.position.copy(p);\n  if (sp.userData.baseLocal) sp.user",
      "Data.baseLocal.copy(p);\n  else sp.userData.baseLocal = p.clone();\n}\n\nfunction update(st, t, flags) {\n  const P = PH;\n  const fol = CUR_MODE === 'follow';\n  /* 跟",
      "随：把整个装置整体下移 (ys − y0)，球壳就永远停在取景框中心；\n     地面/天花板/碰撞刻度则相对它在动 —— 这就是\"镜头跟着球壳\"。 */\n  if (OBJ.root) OBJ.root.position.y = fol ? -(st.ys - FOLLOW.y0) * SC : 0;\n  const",
