      "\n    s.vMax = vMaxOf(s.sid);\r\n  }\r\n}\r\n\r\nPLANS.s1 = makePlan('s1');\r\nPLANS.s2 = makePlan('s2');\r\nPLANS.s3 = makePlan('s3');\r\n\r\nconst S1 = sitOf('s1', { tag: '第(1",
      ")问', label: '① 临界', title: '临界最小速度' });\r\nconst S2 = sitOf('s2', { tag: '第(2)问', label: '② 全程', title: '两圈缠绕后断绳' });\r\nconst S3 = sitOf('s3', {\r\n  tag: '第(3)问', l",
      "abel: '③ 极值',\r\n  title: '拖 h 扫两个极值',\r\n  params: [{\r\n    id: 'h', label: '<span><i>h</i> = MN</span>',\r\n    min: +(5 / 3).toFixed(4), max: +(30 / 7).toFixed(4), ",
