      " = o; while (p) { if (!p.visible) return false; p = p.parent; } return true; }\n\nfunction makeLabelSprite(text, color, size) {\n  const c = document.createElement",
      "('canvas');\n  c.width = 256; c.height = 128;\n  const g = c.getContext('2d');\n  let fs = 92;\n  g.font = 'bold ' + fs + 'px \"Microsoft YaHei\",sans-serif';\n  const",
      " tw0 = g.measureText(text).width;\n  if (tw0 > 236) { fs = Math.max(26, Math.floor(fs * 236 / tw0)); g.font = 'bold ' + fs + 'px \"Microsoft YaHei\",sans-serif'; }",
      "\n  g.textAlign = 'center'; g.textBaseline = 'middle';\n  g.shadowColor = 'rgba(2,6,14,.95)'; g.shadowBlur = 10;\n  g.fillStyle = color;\n  g.fillText(text, 128, 68",
      ");\n  const tex = new THREE.CanvasTexture(c);\n  tex.minFilter = THREE.LinearFilter;\n  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparen",
      "t: true, depthTest: false, depthWrite: false }));\n  sp.scale.set(size * 2, size, 1);\n  sp.renderOrder = 999;\n  const tw = g.measureText(text).width;\n  sp.userDa",
      "ta.baseW = size * 2;\n  sp.userData.baseH = size;\n  sp.userData.hw0 = 0.5 * Math.min(236, tw) * size / 128;\n  sp.userData.hh0 = 0.5 * fs * size / 128;\n  sp.userD",
      "ata.hwU = sp.userData.hw0;\n  sp.userData.hhU = sp.userData.hh0;\n  sp.userData.label = text;\n  LABELS.push({ n: text, sp: sp });\n  return sp;\n}\nfunction setLabel",
      "Scale(k) {\n  if (Math.abs(k - LBL_K) < 0.01) return;\n  LBL_K = k;\n  for (let i = 0; i < LABELS.length; i++) {\n    const sp = LABELS[i].sp;\n    if (!sp || !sp.us",
      "erData.baseW) continue;\n    sp.scale.set(sp.userData.baseW * k, sp.userData.baseH * k, 1);\n    sp.userData.hwU = sp.userData.hw0 * k;\n    sp.userData.hhU = sp.u",
      "serData.hh0 * k;\n  }\n}\n\nconst ARROW_HEAD_RATIO = 2.5;\nfunction makeArrow(color, radius) {\n  const g = new THREE.Group();\n  const mat = new THREE.MeshBasicMateri",
      "al({ color: color, transparent: true, opacity: 1 });\n  const shaftGeo = new THREE.CylinderGeometry(radius, radius, 1, 10);\n  shaftGeo.translate(0, 0.5, 0);\n  co",
      "nst headGeo = new THREE.ConeGeometry(radius * ARROW_HEAD_RATIO, 1, 14);\n  headGeo.translate(0, 0.5, 0);\n  const shaft = new THREE.Mesh(shaftGeo, mat);\n  const h",
      "ead = new THREE.Mesh(headGeo, mat);\n  g.add(shaft); g.add(head);\n  g.userData = { shaft: shaft, head: head, mat: mat, radius: radius };\n  return g;\n}\nfunction s",
      "etArrow(g, origin, dir, len, alpha, headFrac) {\n  const hf = headFrac || 0.32;\n  const headLen = Math.min(0.22, Math.max(0.052, len * hf));\n  g.position.copy(or",
