      "eShadow(size) {\n  const m = new THREE.Mesh(new THREE.PlaneGeometry(size, size),\n    new THREE.MeshBasicMaterial({ map: SHADOW_TEX, transparent: true, depthWrite",
      ": false, opacity: 0.66 }));\n  m.rotation.x = -Math.PI / 2;\n  m.renderOrder = 2;\n  return m;\n}\nfunction makeGrid(size, div, y, c1, c2) {\n  const grid = new THREE",
      ".GridHelper(size, div, c1 == null ? 0x2a4470 : c1, c2 == null ? 0x16263f : c2);\n  grid.position.y = (y == null ? 0 : y);\n  grid.material.transparent = true; gri",
      "d.material.opacity = 0.70;\n  return grid;\n}\n\n/* ======================= 1. 覆盖层实测 ======================= */\nfunction overlayOpacity(el) {\n  const cs = getComput",
      "edStyle(el);\n  if (cs.display === 'none') return 0;\n  /* .legend / .badge 靠 .show 显隐，且带 opacity 过渡：\n     刚 add('show') 的那一帧，computed opacity 还在 0 → 1 的路上（读到 ~0）",
      "，\n     取景就会把它当\"不存在\"，0.2 s 后它才压上来。这里以\"目标态\"为准。 */\n  if (el.classList.contains('show')) return 1;\n  return parseFloat(cs.opacity) < 0.15 ? 0 : 1;\n}\nfunction bottom",
      "OverlayPx() {\n  const sr = stage.getBoundingClientRect();\n  let m = 0;\n  ['.legend', '.badge'].forEach(function (sel) {\n    const el = document.querySelector(se",
      "l); if (!el || !overlayOpacity(el)) return;\n    const r = el.getBoundingClientRect();\n    /* 只有\"真的落在下半屏\"才算底部障碍：窄屏会把徽标挪到顶部，那时它压的是上边界 */\n    if (r.height > 1 && r",
      ".top > sr.top + sr.height * 0.5) m = Math.max(m, sr.bottom - r.top);\n  });\n  const p = $('panel');\n  if (p) m = Math.max(m, sr.bottom - p.getBoundingClientRect(",
      ").top);\n  return m;\n}\nfunction topOverlayPx() {\n  const sr = stage.getBoundingClientRect();\n  let m = 0;\n  ['.hud', '.chartCard:not(.full)'].forEach(function (s",
      "el) {\n    const el = document.querySelector(sel); if (!el || !overlayOpacity(el)) return;\n    const r = el.getBoundingClientRect();\n    if (r.height > 1) m = Ma",
      "th.max(m, r.bottom - sr.top);\n  });\n  return m;\n}\nfunction leftOverlayPx() {\n  const el = $('stem');\n  if (!el || el.classList.contains('collapsed') || !overlay",
      "Opacity(el)) return 0;\n  const sr = stage.getBoundingClientRect();\n  const r = el.getBoundingClientRect();\n  if (r.width < 1 || r.height < 1) return 0;\n  return",
