      "t.remove('show'); }\n\nfunction updateLegend() {\n  const el = $('legend');\n  const lg = SIT().legend ? SIT().legend(stCur(simT), flags()) : null;\n  const items = ",
      "lg && lg.items ? lg.items : [];\n  if (!items.length) { el.classList.remove('show'); el.innerHTML = ''; layoutStem(); return; }\n  el.innerHTML = (lg.title ? '<sp",
      "an class=\"lg-t\">' + lg.title + '</span>' : '') + items.join('');\n  el.classList.add('show');\n  layoutStem();\n}\n\n/* ======================= 6. v-t 图 ============",
      "=========== */\nconst chartCanvas = document.getElementById('chart');\nlet chartW = 0, chartH = 0, chartCache = null;\nfunction resizeChart() {\n  if (!chartCanvas)",
