      "ixelRatio || 1, 2);\n  chartW = r.width; chartH = r.height;\n  chartCanvas.width = Math.round(r.width * dpr);\n  chartCanvas.height = Math.round(r.height * dpr);\n ",
      " chartCanvas.getContext('2d').setTransform(dpr, 0, 0, dpr, 0, 0);\n  chartCache = null;\n}\nfunction buildChartCache() {\n  const series = (SIT().curves ? SIT().cur",
      "ves() : []).slice();\n  chartCache = {\n    sit: curSit, W: chartW, H: chartH, T: T(),\n    series: series,\n    vMax: (typeof SIT().vMax === 'function' ? SIT().vMa",
      "x() : (SIT().vMax || 1)),\n    vMin: (typeof SIT().vMin === 'function' ? SIT().vMin() : (SIT().vMin || 0))\n  };\n  const leg = $('chartLeg');\n  if (leg) leg.inner",
      "HTML = series.map(function (s) {\n    return '<i style=\"background:' + s.color + '\"></i>' + (s.name || s.k);\n  }).join('');\n}\nfunction niceStep(range, target) {\n",
      "  const raw = Math.max(1e-6, range / Math.max(1, target));\n  const p = Math.pow(10, Math.floor(Math.log10(raw)));\n  const m = raw / p;\n  const s = m < 1.5 ? 1 :",
      " (m < 3 ? 2 : (m < 7 ? 5 : 10));\n  return s * p;\n}\nfunction drawChart() {\n  if (!chartCanvas) return;\n  /* CSS 尺寸变了就立即重算（全屏切换/布局变化不一定伴随 resize 事件），\n     否则 canv",
      "as 的位图尺寸与显示尺寸脱节，整张图会被拉伸变形。 */\n  const rr = chartCanvas.getBoundingClientRect();\n  if (!rr.width || !rr.height) { chartW = 0; chartH = 0; return; }\n  if (Math.ab",
      "s(rr.width - chartW) > 0.5 || Math.abs(rr.height - chartH) > 0.5) resizeChart();\n  if (!chartW || !chartH) return;\n  if (!chartCache || chartCache.W !== chartW ",
      "|| chartCache.H !== chartH || chartCache.sit !== curSit) buildChartCache();\n  const g = chartCanvas.getContext('2d');\n  g.clearRect(0, 0, chartW, chartH);\n  /* ",
      "尺寸自适应：卡片放大后字号/线宽一起放大，否则图越大、字越显小。\n     上限 3.0 是给全屏态的（1280 宽的图上 12.5px 字根本看不清）。 */\n  const k = Math.min(3.0, Math.max(0.82, chartW / 320));\n  const padL = Math.ro",
      "und(44 * k), padR = Math.round(14 * k);\n  const padT = Math.round(13 * k), padB = Math.round(25 * k);\n  const W = chartW - padL - padR, H = chartH - padT - padB",
      ";\n  if (W < 20 || H < 20) return;\n  const Tt = chartCache.T, vMax = chartCache.vMax, vMin = Math.min(0, chartCache.vMin);\n  const X = function (t) { return padL",
      " + t / Tt * W; };\n  /* 上下各留 6% 余量：最高/最低刻度不能正好压在画布边缘上（会切掉半个数字） */\n  const span0 = Math.max(1e-6, vMax - vMin);\n  const vTop = vMax + span0 * 0.10, vBot = vMin - ",
      "span0 * 0.04;\n  const Y = function (v) { return padT + (1 - (v - vBot) / (vTop - vBot)) * H; };\n  const FONT = 'px \"Segoe UI\",\"Microsoft YaHei\",sans-serif';\n\n  ",
      "const span = Math.max(1e-6, vMax - vMin);\n  const step = niceStep(span, 5);\n  const ticks = [];\n  for (let v = Math.ceil(vMin / step) * step; v <= vMax + 1e-9; ",
      "v += step) ticks.push(+v.toFixed(6));\n\n  g.strokeStyle = 'rgba(70,95,145,.40)'; g.lineWidth = 1.4 * k;\n  ticks.forEach(function (v) {\n    g.beginPath(); g.moveT",
      "o(padL, Y(v)); g.lineTo(padL + W, Y(v)); g.stroke();\n  });\n  g.strokeStyle = 'rgba(160,190,235,.85)'; g.lineWidth = 2.2 * k;\n  g.beginPath(); g.moveTo(padL, pad",
      "T); g.lineTo(padL, padT + H); g.stroke();\n  g.beginPath(); g.moveTo(padL, Y(0)); g.lineTo(padL + W, Y(0)); g.stroke();\n  const arrow = function (x, y, dx, dy) {",
      "\n    const A = 8 * k, Bh = 4.4 * k;\n    g.beginPath(); g.moveTo(x, y);\n    g.lineTo(x - dx * A - dy * Bh, y - dy * A - dx * Bh);\n    g.lineTo(x - dx * A + dy * ",
