      "];\n  ticks.forEach(function (v) {\n    const major = (v === 0 || Math.abs(v - topTick) < 1e-9 || Math.abs(v - botTick) < 1e-9);\n    if (!major && chartW <= 250) ",
      "return;\n    g.fillStyle = major ? '#a9bcd8' : 'rgba(143,163,192,.62)';\n    g.font = (major ? 'bold ' : '') + ((major ? 12.5 : 10.5) * k).toFixed(1) + FONT;\n    ",
      "g.fillText(String(+v.toFixed(2)), padL - 7 * k, Y(v));\n  });\n  g.textAlign = 'center'; g.textBaseline = 'top';\n  g.fillStyle = '#a9bcd8'; g.font = 'bold ' + (12",
      ".5 * k).toFixed(1) + FONT;\n  g.fillText('0', padL, Y(0) + 6 * k);\n  g.fillText(Tt.toFixed(1), padL + W, Y(0) + 6 * k);\n  g.save();\n  g.translate(9 * k, padT + H",
      " * 0.45); g.rotate(-Math.PI / 2);\n  g.fillStyle = '#8fa3c0'; g.font = (11.5 * k).toFixed(1) + FONT;\n  g.textAlign = 'center'; g.textBaseline = 'middle';\n  g.fil",
      "lText(SIT().yLabel || 'v', 0, 0);\n  g.restore();\n\n  /* 关键事件竖线 */\n  const marks = SIT().marks ? SIT().marks() : [];\n  g.save();\n  g.setLineDash([4 * k, 4 * k]); ",
