      "\n\r\n  OBJ.dimR.geometry.setFromPoints([W(x0, 0, 0.001), W(x0, 1, 0.001)]);\r\n  OBJ.dimR.geometry.computeBoundingSphere();\r\n  OBJ.dimL.geometry.setFromPoints([W(x0",
      ", 1, 0.001), W(x0, ro, 0.001)]);\r\n  OBJ.dimL.geometry.computeBoundingSphere();\r\n\r\n  OBJ.lbR.position.set(SZ(x0), SZ(0.5), SZ(0.22));\r\n  OBJ.lbL.position.set(SZ(",
